using System.Text.Json;

namespace MyApp.Evals.Tests;

[TestClass]
public sealed class CompareTests
{
    public static IEnumerable<object[]> Matrix() =>
        MatrixLoader.Load().Select(e => new object[] { e });

    [TestMethod, DynamicData(nameof(Matrix), DynamicDataSourceType.Method)]
    public async Task RunEntry(MatrixEntry entry)
    {
        var reporting = DiskBasedReportingConfiguration.Create(
            storageRootPath: ReportingConfig.StorageRoot,
            evaluators: ReportingConfig.EvaluatorList(),
            chatConfiguration: new ChatConfiguration(
                Wire.ResolveJudgeClient(Wire.ResolveAgentClient(entry.ModelAssignments))),
            enableResponseCaching: true,
            executionName: $"compare-{entry.Name}");

        foreach (var g in GoldenLoader.Load())
        {
            var scenarioName = $"Compare.{entry.Name}.{g.Id}";
            await using var run = await reporting.CreateScenarioRunAsync(scenarioName);

            var agent = run.ChatConfiguration!.ChatClient;
            var messages = new List<ChatMessage>
            {
                new(ChatRole.System, RubricLoader.SystemPrompt()),
                new(ChatRole.User, g.UserMessage),
            };
            var response = await agent.GetResponseAsync(messages);

            var contexts = new List<EvaluationContext>();
            if (!string.IsNullOrEmpty(g.ReferenceResponse))
            {
                contexts.Add(new BLEUEvaluatorContext(new[] { g.ReferenceResponse }));
                contexts.Add(new GLEUEvaluatorContext(new[] { g.ReferenceResponse }));
                contexts.Add(new F1EvaluatorContext(g.ReferenceResponse));
                contexts.Add(new EquivalenceEvaluatorContext(g.ReferenceResponse));
                contexts.Add(new CompletenessEvaluatorContext(g.ReferenceResponse));
            }
            if (!string.IsNullOrEmpty(g.Context))
                contexts.Add(new GroundednessEvaluatorContext(g.Context));

            await run.EvaluateAsync(messages, response, contexts);
        }
    }
}

internal sealed record MatrixRoot(int SchemaVersion, List<MatrixEntry> Entries);
