namespace MyApp.Evals.Tests;

internal static class AgentChatClientFactory
{
    /// <summary>
    /// Resolves the same IChatClient the app uses, by building a minimal
    /// host that mirrors the app's DI registration.
    /// Detected: AddAzureOpenAIChatClient("chat", "gpt-4o-mini") at AppHost.cs:2
    /// </summary>
    public static IChatClient Create()
    {
        var builder = Host.CreateApplicationBuilder();

        // In test hosts (`dotnet test`), the entry assembly is testhost.exe so
        // user-secrets are NOT auto-loaded by CreateApplicationBuilder.
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);

        // Mirror the AppHost registration: reads ConnectionStrings:chat
        var connectionString = builder.Configuration.GetConnectionString("chat");
        if (string.IsNullOrEmpty(connectionString))
        {
            throw new InvalidOperationException(
                "EVAL_USE_REAL_AGENT=1 but ConnectionStrings:chat is not configured. " +
                "The detected registration (AddAzureOpenAIChatClient(\"chat\", \"gpt-4o-mini\")) " +
                "reads connection string \"chat\" from configuration. Aspire's AppHost populates " +
                "this at runtime, but `dotnet test` runs standalone. Wire one of:\n" +
                "  # Key-based auth:\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;Key=<key>;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "  # Entra-ID auth (DefaultAzureCredential):\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "Note: the hostname strips dashes from the resource name.");
        }

        // Parse connection string and build an Azure OpenAI client
        var parts = connectionString.Split(';')
            .Select(p => p.Split('=', 2))
            .Where(p => p.Length == 2)
            .ToDictionary(p => p[0].Trim(), p => p[1].Trim(), StringComparer.OrdinalIgnoreCase);

        parts.TryGetValue("Endpoint", out var endpoint);
        parts.TryGetValue("DeploymentId", out var deploymentId);
        deploymentId ??= "chat";

        if (string.IsNullOrEmpty(endpoint))
            throw new InvalidOperationException(
                "ConnectionStrings:chat is set but missing an Endpoint= segment.");

        // Use MEAI's OpenAI client against the Azure endpoint
        var options = new Azure.AI.OpenAI.AzureOpenAIClientOptions();
        Azure.AI.OpenAI.AzureOpenAIClient azureClient;

        if (parts.TryGetValue("Key", out var key) && !string.IsNullOrEmpty(key))
        {
            azureClient = new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint), new System.ClientModel.ApiKeyCredential(key), options);
        }
        else
        {
            azureClient = new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint), new Azure.Identity.DefaultAzureCredential(), options);
        }

        return azureClient.GetChatClient(deploymentId).AsIChatClient();
    }
}

